"use client";

import Link from "next/link";
import { useRouter } from "next/navigation";
import {
  AlertTriangle, Bike, CarFront, CheckCircle2, ChevronRight, CircleDollarSign, Clock3, FileCheck2, Gauge, History, IdCard,
  LoaderCircle, MapPin, Navigation, PackageCheck, Phone, Play, ReceiptText, RefreshCw, ShieldCheck, ShoppingBasket, Truck, Upload, UserRound, WalletCards, X
} from "lucide-react";
import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { PortalShell } from "@/components/portal-shell";
import { AuthGate } from "@/components/auth-gate";
